import subprocess, re, math

def call(*args):
    p=subprocess.run(args,text=True,capture_output=True)
    print('$ '+' '.join(args)+'\n'+p.stdout,flush=True)
    if p.returncode: raise RuntimeError(p.stderr or p.stdout)
    return p.stdout

def locate():
    s=call('vision','locate')
    m=re.search(r'lower end x=([-\d.]+) y=([-\d.]+) z=([-\d.]+) mm; tilt ([-\d.]+)',s)
    if not m: raise RuntimeError('Peg not visible')
    return tuple(map(float,m.groups()))

# Joint waypoints taken from the documented human demonstration, episode 2.
# They provide a grasp/transfer seed despite the unrecalibrated right-arm offsets.
def joint(q): call('robot','joints','right',*q.split())
call('trial','start')
call('robot','pick','cap','--arm','left')
call('robot','place','bin','--arm','left')
call('robot','grip','right','open')
joint('-0.466 -0.032 0.341 3.142 -1.254 -0.466')
joint('-0.466 0.093 0.504 3.142 -0.970 -0.466')
call('robot','grip','right','close')
joint('-0.466 -0.032 0.341 3.142 -1.254 -0.466')
s=call('robot','status')
if 'right gripper' in s: pass
if 'right arm:' not in s or 'gripper closed on an object' not in s: raise RuntimeError('Grasp not confirmed')
x,y,z,tilt=locate()
if tilt>3.5 or z<70: raise RuntimeError('Unsafe grasp geometry')
joint('-0.174 0.424 -0.264 3.142 -1.403 -0.174')
for i in range(18):
    x,y,z,tilt=locate()
    if tilt>3.5: raise RuntimeError('Excessive tilt')
    if z<=16.5 and abs(x)<1.5 and abs(y-60)<1.5:
        call('robot','grip','right','open')
        call('robot','step','right','0','0','20')
        call('trial','end')
        break
    dx=max(-5,min(5,0.5-x)); dy=max(-5,min(5,60-y))
    dz=-min(12,max(0,z-16.5))
    if z>57 and (abs(x-0.5)>2 or abs(y-60)>2): dz=-min(10,max(0,z-62))
    s=call('robot','step','right',f'{dx:.2f}',f'{dy:.2f}',f'{dz:.2f}')
    f=call('robot','force','right')
    values=[float(v) for v in re.findall(r'F[xyz]=([+-]?[\d.]+)',f)]
    if 'stop' in s.lower() or (values and math.sqrt(sum(v*v for v in values))>20):
        raise RuntimeError('Contact guard: stop and inspect')
else: raise RuntimeError('Feedback iteration limit')
